-- S1 — roles, the capability split, and assignment (journeys build plan §5
-- "S1"). Two new `Role` values (`SALES`, `DESIGNER`) and the two assignment
-- edges on `Contract` (`designerId`, `developerId`), each nullable with
-- ON DELETE SET NULL: an assignee is chosen by sales and changed by them, a
-- contract never depends on one existing, and deleting an account must never
-- take a contract with it.
--
-- Generated by `prisma migrate dev --create-only` and read. Nothing here is
-- beyond what Prisma expresses, so there is no hand-written part: no CHECK
-- (the "an assignee must hold the matching capability and be ACTIVE" rule is
-- a *write-time* check in `assignContract`, not an invariant — a designer
-- later disabled stays on the row as history, plan S1), and no backfill
-- (production holds no data, plan P0-1; the seed gains the new accounts).
--
-- Two `ADD VALUE`s in one migration is fine on Postgres 12+ (this runs 16):
-- a value added inside a transaction only cannot be *used* in that same
-- transaction, and nothing below uses either.

ALTER TYPE "Role" ADD VALUE 'SALES';
ALTER TYPE "Role" ADD VALUE 'DESIGNER';

-- AlterTable
ALTER TABLE "Contract" ADD COLUMN     "designerId" TEXT,
ADD COLUMN     "developerId" TEXT;

-- CreateIndex
CREATE INDEX "Contract_designerId_idx" ON "Contract"("designerId");

-- CreateIndex
CREATE INDEX "Contract_developerId_idx" ON "Contract"("developerId");

-- AddForeignKey
ALTER TABLE "Contract" ADD CONSTRAINT "Contract_designerId_fkey" FOREIGN KEY ("designerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "Contract" ADD CONSTRAINT "Contract_developerId_fkey" FOREIGN KEY ("developerId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
